.escura-accordion {
  border-bottom: 1px solid #ddd;
  margin-bottom: 10px;
  background-color: #fff;
}
.escura-accordion summary {
  font-size: 1.1rem;
  font-weight: bold;
  color: #677767; /* 品牌主色調 */
  padding: 15px 10px;
  cursor: pointer;
  list-style: none; /* 隱藏預設箭頭 */
  position: relative;
  border-left: 4px solid #677767;
  transition: background-color 0.3s ease; /* 恢復原本單純的背景過渡效果 */
}

